import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E5%8E%9F%E8%AB%96%E6%96%87%E3%81%8B%E3%82%89%E8%A7%A3%E3%81%8D%E6%98%8E%E3%81%8B%E3%81%99%E7%94%9F%E6%88%90AI.html","title":"原論文から解き明かす生成AI","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":5.26,"words":1578},"filePathRelative":"原論文から解き明かす生成AI.md"}`),a={name:`原論文から解き明かす生成AI.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="原論文から解き明かす生成ai" tabindex="-1"><a class="header-anchor" href="#原論文から解き明かす生成ai"><span>原論文から解き明かす生成AI</span></a></h1><p><a href="./書籍.html">書籍</a>, <a href="./機械学習.html">機械学習</a></p><ul><li><a href="https://amzn.to/4voWeSZ" target="_blank" rel="noopener noreferrer">amazon: 原論文から解き明かす生成AI</a></li><li><a href="https://github.com/yoheikikuta/support-genAI-book" target="_blank" rel="noopener noreferrer">原論文から解き明かす生成AIのサポートページ</a></li><li><a href="./一人読書会ライブ.html">一人読書会ライブ</a> まずはこの本を題材にやってるのでリンク貼っておく。</li></ul><p>菊田先生のありがたい本。</p><h2 id="読み始め-2026-06-01-月" tabindex="-1"><a class="header-anchor" href="#読み始め-2026-06-01-月"><span>読み始め　2026-06-01 (月)</span></a></h2><p>買ってはいたのだが機械学習系の仕事も離れていたし、という事で読んでいなかった。 無職になったのでなんか教科書っぽいものとか読みたいな、と思っていたので、この本を読んでみる。 あまりこの辺に関わる事は無さそうな気もするが、 直接役に立たない事を学ぶのが無職の本懐というものだろう、ということで。</p><p>まずは第一章の最初の方を読む程度。</p><h2 id="_1章のメモ-2026-06-09-火" tabindex="-1"><a class="header-anchor" href="#_1章のメモ-2026-06-09-火"><span>1章のメモ 2026-06-09 (火)</span></a></h2><h3 id="自分の力で論文を読み解くための技術" tabindex="-1"><a class="header-anchor" href="#自分の力で論文を読み解くための技術"><span>自分の力で論文を読み解くための技術</span></a></h3><ul><li>議論が成立する条件を確認する</li><li>具体例を構成する <ul><li>評価指標の具体例 <ul><li>パープレキシティの例</li><li>演習問題1.1, accuracy, precision, recall</li></ul></li><li>主張を確認するための具体例 <ul><li>back propagationの計算量</li><li>生成AIを実際に触ってみて確認</li></ul></li><li>仮定が成り立たない例を考える <ul><li>Markovじゃないとは</li><li>次トークン予測がうまくいきにくい例とは</li></ul></li></ul></li><li>実装を読み解いて理解を深める</li><li>重要な参考文献は踏み込んで調べる <ul><li>ハブ</li><li>データセット</li><li>教科書はどうか？</li></ul></li><li>アウトプットする事で理解を深める <ul><li>他人に内容を説明</li><li>github issueに読んだメモを書く</li><li>ライブはどうか？</li></ul></li></ul><p>単語</p><ul><li>hypotenuse: 斜辺</li><li>right triangle: 直角三角形</li><li>inscribed circle: 内接円</li></ul><h3 id="自分以外の力" tabindex="-1"><a class="header-anchor" href="#自分以外の力"><span>自分以外の力</span></a></h3><ul><li>少人数で深く議論する</li><li>論文の著者に直接質問する</li><li>ウェブ上で議論する</li><li>生成AIを使う</li></ul><h3 id="ノーテーション" tabindex="-1"><a class="header-anchor" href="#ノーテーション"><span>ノーテーション</span></a></h3><p>Pは珍しい。logは自然対数。Cover and Thomasやサイコロ本は2を前提にした話が多いので注意が必要。</p><h3 id="universal-approximation-theorem" tabindex="-1"><a class="header-anchor" href="#universal-approximation-theorem"><span>Universal Approximation Theorem</span></a></h3><p><a href="./ApproximationBySuperpositionsOfASigmoidalFunction.html">ApproximationBySuperpositionsOfASigmoidalFunction</a></p><h3 id="perplexity" tabindex="-1"><a class="header-anchor" href="#perplexity"><span>Perplexity</span></a></h3><p><a href="./サイコロ本.html">サイコロ本</a>と<a href="./CoverAndThomas.html">CoverAndThomas</a>を復習する。</p><p>導出にAsymptotic Equipartition Propertyが使われてる…（Cover and Thomasの3章のテーマ）</p><h3 id="実装を読む、の正規表現" tabindex="-1"><a class="header-anchor" href="#実装を読む、の正規表現"><span>実装を読む、の正規表現</span></a></h3><p>使う方は以下で、</p><p><a href="https://github.com/openai/gpt-2/blob/9b63575/src/encoder.py#L98C25-L98C32" target="_blank" rel="noopener noreferrer">gpt-2/src/encoder.py at 9b63575ef42771a015060c964af2c3da4cf7c8ab · openai/gpt-2</a></p><p>該当箇所のコードを抜き出すと以下になっている（self.patが本文ででてきた正規表現）</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">for</span> token <span class="token keyword">in</span> re<span class="token punctuation">.</span>findall<span class="token punctuation">(</span>self<span class="token punctuation">.</span>pat<span class="token punctuation">,</span> text<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    token <span class="token operator">=</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">.</span>join<span class="token punctuation">(</span>self<span class="token punctuation">.</span>byte_encoder<span class="token punctuation">[</span>b<span class="token punctuation">]</span> <span class="token keyword">for</span> b <span class="token keyword">in</span> token<span class="token punctuation">.</span>encode<span class="token punctuation">(</span><span class="token string">&#39;utf-8&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    bpe_tokens<span class="token punctuation">.</span>extend<span class="token punctuation">(</span>self<span class="token punctuation">.</span>encoder<span class="token punctuation">[</span>bpe_token<span class="token punctuation">]</span> <span class="token keyword">for</span> bpe_token <span class="token keyword">in</span> self<span class="token punctuation">.</span>bpe<span class="token punctuation">(</span>token<span class="token punctuation">)</span><span class="token punctuation">.</span>split<span class="token punctuation">(</span><span class="token string">&#39; &#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>self.bpeを読まないと詳しい事は分からないが、tokenごとに別のbpeとなるようにしている、という理解でいいのかな。</p><h3 id="_1章感想ライブ-2026-06-12-金-20時" tabindex="-1"><a class="header-anchor" href="#_1章感想ライブ-2026-06-12-金-20時"><span>1章感想ライブ 2026-06-12 (金) 20時</span></a></h3><p>iLMiNAでライブしてみる試み。どう進めるかはあんまり考えてないが先頭からぱらぱら見つつ思った事とか計算したりとかそういうの。 なんか名前が欲しいな。一人読書会ライブ、とかか？</p><p>やってみた所、1.2.2.1までで結構な時間になったので次回は別の日に（Perplexityの手前まで）。</p><p>感想: <a href="https://karino2.github.io/2026/06/13/self_bookreading_live.html" target="_blank" rel="noopener noreferrer">一人読書会ライブ - なーんだ、ただの水たまりじゃないか</a></p><p><a href="./一人読書会ライブ.html">一人読書会ライブ</a></p><h3 id="_1章感想ライブ続き-2026-06-14-日" tabindex="-1"><a class="header-anchor" href="#_1章感想ライブ続き-2026-06-14-日"><span>1章感想ライブ続き 2026-06-14 (日)</span></a></h3><p><a href="https://www.youtube.com/watch?v=PR8iWLJLZi0&amp;list=PL3J_mLcl4YCfAUWElMC438W6SDbIoZRg9&amp;index=3" target="_blank" rel="noopener noreferrer">一人読書会ライブ: 原論文から解き明かす生成AI、1.2.2.2から - YouTube</a></p><h2 id="_2章-2026-06-13-土" tabindex="-1"><a class="header-anchor" href="#_2章-2026-06-13-土"><span>2章 2026-06-13 (土)</span></a></h2><h3 id="カラースペースの話" tabindex="-1"><a class="header-anchor" href="#カラースペースの話"><span>カラースペースの話</span></a></h3><p>Colormetric color spaceの話とか<a href="./ガンマ補正.html">ガンマ補正</a>とかを考えると、もうちょっと考えるべき事がある。</p><p>sRGBはCRTのガンマ値になっているので、そのままCRTに渡すと光のintensityがリニアになるようになっている（ガンマは2.2）。 <a href="./ガンマ補正.html">ガンマ補正</a>の所にあるようにこれのlineariseは場合分けした二つの関数の接続となっている。</p><p><a href="./CG.html">CG</a>から<a href="./【書籍】PrinciplesOfDigitalImageProcessing.html">【書籍】PrinciplesOfDigitalImageProcessing</a>のCore Algorithmの6章あたりの話で、CIE XYZとかCIE Labの話がある。 なお、<a href="./MFG.html">MFG</a>ではCIE XYZへの変換をbuiltinでサポートしている。最近はOK Labを使うのが流行りのよう（あまり知らないが）。</p><p>RGBはCRTベースの話なので、より人間の知覚に沿った色空間が実験とかから定義されていて、それの基礎がCIE XYZ。 さらにそれをlinearになるように変換したものがCIE LuvやCIE Lab。</p><p>これらの処理を全部無視してフィーチャーとして使って、これらの変換を学習させる事は出来るだろうけれど、 それが何をしているかは理解していたいものだ。</p><h3 id="分布仮説の論文読み" tabindex="-1"><a class="header-anchor" href="#分布仮説の論文読み"><span>分布仮説の論文読み</span></a></h3><p><a href="./ContextualCorrelatesOfSynonymy.html">ContextualCorrelatesOfSynonymy</a></p><h2 id="一人読書会ライブ、分布仮説" tabindex="-1"><a class="header-anchor" href="#一人読書会ライブ、分布仮説"><span>一人読書会ライブ、分布仮説</span></a></h2><ul><li><a href="https://www.youtube.com/live/mN5_whp03DE" target="_blank" rel="noopener noreferrer">一人読書会ライブ: 原論文から解き明かす生成AI、2.1分布仮説 - YouTube</a></li><li><a href="https://www.youtube.com/live/CQ4yysTesZk" target="_blank" rel="noopener noreferrer">一人読書会ライブ: 原論文から解き明かす生成AI、2.1分布仮説続き - YouTube</a></li></ul><h2 id="nmt-subword" tabindex="-1"><a class="header-anchor" href="#nmt-subword"><span>NMT subword</span></a></h2><p><a href="./NeuralMachineTranslationOfRareWordsWithSubwordUnits.html">NeuralMachineTranslationOfRareWordsWithSubwordUnits</a></p><h2 id="subowrdregularization" tabindex="-1"><a class="header-anchor" href="#subowrdregularization"><span>SubowrdRegularization</span></a></h2><p><a href="./SubwordRegularization.html">SubwordRegularization</a></p><h3 id="amazonの低評価レビューの話" tabindex="-1"><a class="header-anchor" href="#amazonの低評価レビューの話"><span>Amazonの低評価レビューの話</span></a></h3><p>この本には「サブワードの出現確率は、サブワードの頻度に依存した確率のみで定まる」が意味分からん、という低評価レビューがついている。 この手のレビューに対しては著者が反論しても意味が無い類のものではあると思うが、この本を読み始める前にこのレビューを読んでいてどんなところなのかと興味があったので該当箇所を見てみる。</p><p>以下は自分が正解かどうかは不明だが自分はこう思う、という話。</p><p>該当箇所は2.4のサブワードユニグラム言語モデルのところで、原文は以下のようになっている。</p><p>「サブワードに対するユニグラム言語モデルは、サブワードの出現確率はそのサブワードの頻度に依存した確率のみで定まるという仮定の下、サブワード列t（以下数学表記で書くのが面倒なので割愛）の生成確率を次のように表現する」（以下数式なので同様に割愛）</p><p>レビューではサブワードの出現確率をこう定義すると言いたいのだろう、と言っているが、それは間違っているように思う。</p><p>この文章はサブワードへの「分割」をどう定式化するか、という方が本題であって、個々のサブワードの生成確率はおまけというかその前提になる。 だから文章としては、カッコ書き扱いとして以下のように解釈すべきに思う。</p><p>「サブワードに対するユニグラム言語モデルは、（サブワードの出現確率はそのサブワードの頻度に依存した確率のみで定まるという仮定の下）サブワード列tの生成確率を次のように表現する」</p><p>サブワードの出現確率がgivenのもとで分割の生成確率は以下のように書けますよ〜、と言いたい訳だ。</p><p>そしてこのカッコは何を言っているか、というと、ようするに「頻度から計算した値をベルヌーイ分布のミューとして使ったベルヌーイ試行として考える事にするので、条件付き確率を考える必要が無く独立した確率として扱う」というような事を言っているように見える。</p><p>特に後者の条件付き確率を考えない、というのがその次のtの式の理由になっているので、重要な所に思う。</p><p>なのでレビューの表現では条件を考えなくて良いという部分が抜け落ちているので、 本書の文章の方がより正確な表現だとは思う。 また、本書の文章の方がベルヌーイ試行との脳内でのマッピングが容易なので自分には分かりやすい。</p><p>けれど不完全な表現を書いているレビューが間違いか？と言われるとちょっと微妙な所もあり、 この本を読んだ結果そのくらいしか読み取れなかった、というのは、それ自体がレビューとして意義のあるものではあるように思う。 実際これは読解能力という話では無く、説明していない背景知識の話に思う。 それを説明していないのはそういう本だからなんだが、その結果文句を言われてもまぁ仕方ないよなぁ、とは思う。</p><p>こうした試行をモデル化する時にベルヌーイ試行が大前提にあるのは、この文章からは読み取れない。 知識が足りているかどうかを自分で判定するのが難しいので、知らない事を学ぶ本としてはいまいちという批判はあっても良い気はする。</p><p>ただsubword regularizationの論文を読むと多項分布がでてくるのでその復習のためにベルヌーイ試行を復習する必要はあって、 それを復習した後に本文を読むとこの辺の事はわかるようにも出来ている。 これを十分な説明と言うのは無理がある、というのに理解は示すが、この件に関しては表現が悪いというよりは前提知識が多いくせに明示されてない、という批判の方が正しいような気はする。</p><h3 id="この本はようするに原論文のファンブックである-攻略本では無い" tabindex="-1"><a class="header-anchor" href="#この本はようするに原論文のファンブックである-攻略本では無い"><span>この本はようするに原論文のファンブックである（攻略本では無い）</span></a></h3><p>自分が思うのは、この本は原論文のファンブックだ、というものだ。 本でなければさおりんと一緒とか初音のないしょとかああいうのだ。 雫や痕をプレイしないであの辺買っても意味が無いのと同じように、 原論文を読まずに本書だけ読んでも全く意味が無いと思う。 いや、俺は月姫は読本しか読んでないよ？という人もいるだろうけれど。</p><p>ファンブックというのは本編を一通り遊んだ人が設定資料とか原画とかを見て楽しむものであって、攻略にはあまり役に立たない。 ただ作品を好きな人がより多く愛を育むための本だ。</p><p>この本は原論文を読んで好きになった人が集まって、どこが良いかを話し合うような本である。 この論文いいよね、とか、論文のここの部分が自分は気になったんだよ、 とか、そういう話をして盛り上がる、という本だ。</p><p>それは原論文を読むモチベーションにもなるので読むのに役に立つ部分もある。 そして楽しみを増す事でより論文というものを好きになって読むのを促進するとは思う。 唯一無二の本ではあるので、こんな本もあってはいいんじゃないか。</p><p>でもたぶん世の中の人が期待してたのはファンブックではなく攻略本なのでは？と思うのだが。</p><h3 id="著者の気になった事と自分の気になる事は違う" tabindex="-1"><a class="header-anchor" href="#著者の気になった事と自分の気になる事は違う"><span>著者の気になった事と自分の気になる事は違う</span></a></h3><p>あと、本書は「自分はこういう所が気になってこの辺の論文のこの辺を読んだ」という話が多いのだが、 この気になる所は読者と同じとは限らない、というか普通は違う。 だからそのまま読んでもあんまり意味は無い。</p><p>こういう事が気になったらこういう所をこう読むのか、という例としては役に立つのだが、 人が気になった所というのはそれ自体は役には立たない。 自分が気になった所を解き明かす方が重要だ。</p><p>実際本書の抜粋されている所では自分が気になった所は全く分からないので意味が全く分からない。 著者は納得したんだろうが読者の自分は何も分からない。</p><p>だから、自分の気になった所は本書とは独立に解き明かす必要がある。</p><p>それを解き明かして理解した上で、はじめて本書の文章には意味がある。 なるほど、菊田さんはこういう所が気になってこう解釈したのか、と。 それは自分がある程度理解した後でないと理解出来ないし、意味も無い。</p><p>この自分の気になった所は先に自分で解き明かしておかないと本書の文章に意味が無い、というのは、読んでみるまではわからなかった事で割と思ってたのと違うな、と思った所だ。</p><p>ただ、自分が一通り理解したあとに読むと本書はなかなか面白い。 面白いので書籍としての価値はあるのではないか、という気はする。</p><p>あと著者がこういう所が気になってこういう風に読んだ、というのは、メタなレベルではそれなりに参考にもなる。 というかそういう事を参考にしたり自分との違いや同じ所を楽しんだりするのが正しい本書の楽しみ方に思う。</p><p>でもそれって論文読んで理解した後なので、相当暇人向けの本だよな〜という気はする。 なお、私は相当暇人である。</p><h2 id="演習問題-2-10" tabindex="-1"><a class="header-anchor" href="#演習問題-2-10"><span>演習問題 2.10</span></a></h2><p>貪欲法よりビームサーチした方がいい例。ようするに後とつながった方がいいのに最初に大きくしすぎるような例であれば良い。どんなのがあるかな？</p><p>「的あて」とかどうだろう？「遠距離的あて」とかを、遠距離的とgreedyに分割してしまうと最後のあての確率が低くなるようなケースだと、 ビームサーチ2でやれば「遠距離」と「的あて」に出来る気はする。</p><h2 id="読書会ライブ2章-2" tabindex="-1"><a class="header-anchor" href="#読書会ライブ2章-2"><span>読書会ライブ2章-2</span></a></h2><ul><li><a href="https://www.youtube.com/live/hSKyxtBWl48" target="_blank" rel="noopener noreferrer">一人読書会ライブ: 原論文から解き明かす生成AI、2章の2、サブワード分割 - YouTube</a></li><li><a href="https://www.youtube.com/live/cHOybn0feyk" target="_blank" rel="noopener noreferrer">一人読書会ライブ: 原論文から解き明かす生成AI、2章の2、サブワード分割、ユニグラム言語モデル〜 - YouTube</a></li></ul><p>参考リンク</p><ul><li><a href="./HMM.html">HMM</a></li><li><a href="./サイコロ本.html">サイコロ本</a></li><li><a href="./アルゴリズム本.html">アルゴリズム本</a></li></ul><h2 id="sentence-pieceのコード理解" tabindex="-1"><a class="header-anchor" href="#sentence-pieceのコード理解"><span>Sentence Pieceのコード理解</span></a></h2><p><a href="./SentencePiece.html">SentencePiece</a>、<a href="./一人読書会ライブ.html">一人読書会ライブ</a>もこの辺を対象にやった。</p><h2 id="バイトのbpe-gpt2の論文" tabindex="-1"><a class="header-anchor" href="#バイトのbpe-gpt2の論文"><span>バイトのBPE（GPT2の論文）</span></a></h2><p>これか。</p><p><a href="https://cdn.openai.com/better-language-models/language_models_are_unsupervised_multitask_learners.pdf" target="_blank" rel="noopener noreferrer">Language Models are Unsupervised Multitask Learners.pdf</a></p><p>トークナイズの所よりもそれ以外の所が興味深い論文ではあるが、GPT2はバイトのBPEか〜と眺めておく意義はあるな。</p><h2 id="toward-a-theory-of-tokenization-in-llms" tabindex="-1"><a class="header-anchor" href="#toward-a-theory-of-tokenization-in-llms"><span>Toward a Theory of Tokenization in LLMs</span></a></h2><p><a href="./TowardATheoryOfTokenizationInLLMs.html">TowardATheoryOfTokenizationInLLMs</a></p><h2 id="_3章-transformer" tabindex="-1"><a class="header-anchor" href="#_3章-transformer"><span>3章 Transformer</span></a></h2><ul><li><a href="./アテンション.html">アテンション</a></li><li><a href="./PositionEmbeddings.html">PositionEmbeddings</a></li><li><a href="./ConvS2S.html">ConvS2S</a></li><li><a href="./Transformer.html">Transformer</a><ul><li><a href="./セルフアテンション.html">セルフアテンション</a></li></ul></li><li><a href="./BatchNormalization.html">BatchNormalization</a></li></ul><h2 id="_4章-gptとテキスト生成" tabindex="-1"><a class="header-anchor" href="#_4章-gptとテキスト生成"><span>4章 GPTとテキスト生成</span></a></h2><ul><li><a href="./GPT1論文.html">GPT1論文</a></li><li><a href="https://arxiv.org/abs/2005.14165" target="_blank" rel="noopener noreferrer">arxiv: 2005.14165 Language Models are Few-Shot Learners</a></li><li><a href="https://arxiv.org/abs/1904.10509" target="_blank" rel="noopener noreferrer">arxiv: 1904.10509 Generating Long Sequences with Sparse Transformers</a></li><li><a href="https://arxiv.org/abs/2303.08774" target="_blank" rel="noopener noreferrer">arxiv: 2303.08774 GPT-4 Technical Report</a></li><li><a href="./強化学習.html">強化学習</a></li></ul><p>式4.16で <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup><msup><mi>X</mi><mi>T</mi></msup></mrow><annotation encoding="application/x-tex">X&#39;X^T</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span></span></span></span> などの項がいらないのは何故か？</p>`,100)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};